      {/capture}
      {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'flex flex-col items-start justify-start gap-0'], 'children' => $c_3])|noescape}
    {/capture}
    {=ui_include('ui/label/label.latte', ['p' => ['Class' => 'flex items-center gap-4 rounded p-4 inset-ring inset-ring-border has-checked:inset-ring-foreground', 'Attrs' => ui_attrs(['data-testid', 'payment'])], 'children' => $c_4])|noescape}
  {/foreach}
{/capture}
